var range = {
  from: 1,
  to: 3,
  [Symbol.iterator]: function () {
    var current = this.from;
    var last = this.to;
    return {
      next: function () {
        if (current <= last) {
          return { value: current++, done: false };
        }
        return { value: undefined, done: true };
      },
    };
  },
};
console.log([...range]);
for (var v of range) {
  console.log(v);
}

